import{_ as t,o as r,c as i,a7 as o}from"./chunks/framework.CWfAgRyf.js";const u=JSON.parse('{"title":"Event handler priority","description":"How to use event priority to control the order of event handlers.","frontmatter":{"title":"Event handler priority","outline":"deep","description":"How to use event priority to control the order of event handlers.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/developers/plugin-docs/events/priority"}]]},"headers":[],"relativePath":"docs/developers/plugin-docs/events/priority.md","filePath":"docs/developers/plugin-docs/events/priority.md","lastUpdated":null}'),s={name:"docs/developers/plugin-docs/events/priority.md"};function n(d,e,a,l,h,c){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="event-handler-priority" tabindex="-1">Event handler priority <a class="header-anchor" href="#event-handler-priority" aria-label="Permalink to &quot;Event handler priority&quot;">​</a></h1><p>Event “priority” is used to control the order in which multiple handlers of the same event will execute. This is mainly used for plugin interoperability. The <code>pocketmine\\event\\EventPriority</code> class declares a series of hardcoded priorities which handlers can use.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>Priority is a misleading name, because higher “priority” means that the handler should execute <em>later</em> in the sequence and not earlier. The reasoning for this is that higher order handlers “get the last word” over lower order handlers. This naming may be changed in future Axolotl-PM versions.</p></div><h2 id="list-of-priorities" tabindex="-1">List of priorities <a class="header-anchor" href="#list-of-priorities" aria-label="Permalink to &quot;List of priorities&quot;">​</a></h2><p>At the time of writing, the following priorities exist:</p><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td>LOWEST</td><td>These handlers will be executed first.<br><br>This should be used when the original event state is needed (before later handlers modify it),<br><br>or when the handler is making a low-priority modification (to allow other handlers to override it).</td></tr><tr><td>LOW</td><td></td></tr><tr><td>NORMAL</td><td>If a priority is not specified, handlers will be registered here by default.</td></tr><tr><td>HIGH</td><td></td></tr><tr><td>HIGHEST</td><td>Handlers registered at this priority get the final say in the event’s outcome.</td></tr><tr><td>MONITOR</td><td>These handlers will execute last.<br><br><strong>No modification to the event’s outcome should be made at this priority, including cancellation</strong>.<br><br>This should be used only for <strong>monitoring the outcome</strong> of an event.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>When multiple handlers are registered to the same priority, the order of execution is undefined.</p></div>',7)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
